  for(const p of state?.players||[]){const o=models.get(p.id);if(!o)continue;o.entity.enabled=p.hp>0&&(p.id!==myId||tps);const pos=o.entity.getPosition().clone(),tx=p.id===myId?local.x:p.x,tz=p.id===myId?local.z:p.z;const moving=Math.hypot(tx-o.lastPos.x,tz-o.lastPos.z)>.015;o.entity.setPosition(pc.math.lerp(pos.x,tx,Math.min(1,dt*16)),p.id===myId?local.y:p.y,pc.math.lerp(pos.z,tz,Math.min(1,dt*16)));o.entity.setEulerAngles(0,(p.id===myId?yaw:p.yaw)*180/Math.PI,0);o.setWeapon(p.weapon);o.update(dt,{moving,sprint:p.sprinting,crouch:p.crouch,reload:!!p.reloadAt,dead:!p.hp});o.lastPos={x:pos.x,z:pos.z}}
  const eye=new pc.Vec3(local.x,local.y+(keys.KeyC?1.2:1.63),local.z),dir=new pc.Vec3(-Math.sin(yaw)*Math.cos(pitch),Math.sin(pitch),-Math.cos(yaw)*Math.cos(pitch));let dist=tps?(aim?1.25:3.0):0;if(tps)for(const b of boxes)dist=Math.min(dist,Math.max(0,rayBox([eye.x,eye.y,eye.z],[-dir.x,-dir.y,-dir.z],b)-.22));
  camera.setPosition(eye.x-dir.x*dist+(tps?.38*Math.cos(yaw):0),eye.y-dir.y*dist+(tps?.18:0),eye.z-dir.z*dist-(tps?.38*Math.sin(yaw):0));camera.setEulerAngles(pitch*180/Math.PI,yaw*180/Math.PI,0);camera.camera.fov=pc.math.lerp(camera.camera.fov,aim?(me?.weapon==='M24'?28:48):68,Math.min(1,dt*12));
  if(me&&me.weapon!==viewWeaponId){viewWeapon.destroy();viewWeaponId=me.weapon;viewWeapon=createWeapon(pc,me.weapon,{viewmodel:true});camera.addChild(viewWeapon)}viewWeapon.enabled=!tps&&!!me?.hp;const recoil=Math.max(0,1-(performance.now()-lastFire)/150),moving=keys.KeyW||keys.KeyS||keys.KeyA||keys.KeyD;viewWeapon.setLocalPosition(aim?0:.24,(aim?-.15:-.26)+(moving?Math.sin(animTime*10)*.012:Math.sin(animTime*1.4)*.003)-(me?.reloadAt?.13:0),-.48+recoil*.07);viewWeapon.setLocalEulerAngles(recoil*3+(me?.reloadAt?30:0),0,me?.reloadAt?-20:0);
  if(performance.now()-lastHud>100){lastHud=performance.now();hud(me)}
